export const mcpSchema = z
	.looseObject({
		server_label: z.string(),
		type: z.enum(["mcp"]),
		allowed_callers: z.union([z.array(z.enum(["direct", "programmatic"])), z.null()]).optional(),
		allowed_tools: z
			.union([z.array(z.string()), mcpAllowedToolsMcpToolFilterSchema, z.null()])
			.optional(),
		authorization: z.union([z.string(), z.null()]).optional(),
		connector_id: z
			.union([
				z.enum([
					"connector_dropbox",
					"connector_gmail",
					"connector_googlecalendar",
					"connector_googledrive",
					"connector_microsoftteams",
					"connector_outlookcalendar",
					"connector_outlookemail",
					"connector_sharepoint",
				]),
				z.null(),
			])
			.optional(),
		defer_loading: z.union([z.boolean(), z.null()]).optional(),
		headers: z.union([z.record(z.string(), z.string()), z.null()]).optional(),
		require_approval: z
			.union([mcpRequireApprovalMcpToolApprovalFilterSchema, z.enum(["always", "never"]), z.null()])
			.optional(),
		server_description: z.union([z.string(), z.null()]).optional(),
		server_url: z.union([z.string(), z.null()]).optional(),
		tunnel_id: z.union([z.string(), z.null()]).optional(),
	})
	.describe(
		"Give the model access to additional tools via remote Model Context Protocol\n(MCP) servers. [Learn more about MCP](https://platform.openai.com/docs/guides/tools-remote-mcp).",
	);

