export const autoRouterCacheBucketSchema = z
	.object({
		turns: z.int().describe("Turns classified into this bucket"),
		hits: z.int().describe("Turns in this bucket whose response reported cache-read tokens"),
		hit_rate_pct: z.number().describe("hits over this bucket's turns, as a percentage"),
	})
	.describe("One prompt-caching bucket of turns, with how often those turns hit the cache.");

export const autoRouterCacheStatsSchema = z
	.object({
		coverage_pct: z.number().describe("Share of turns that carried cache telemetry"),
		hit_rate_pct: z.number().describe("All cache hits over telemetry-bearing turns"),
		same_model: autoRouterCacheBucketSchema.describe(
			"One prompt-caching bucket of turns, with how often those turns hit the cache.",
		),
		first_visit: autoRouterCacheBucketSchema.describe(
			"One prompt-caching bucket of turns, with how often those turns hit the cache.",
		),
		return_to_tier: autoRouterCacheBucketSchema.describe(
			"One prompt-caching bucket of turns, with how often those turns hit the cache.",
		),
		unordered_turns: z.int().describe("Turns that arrived out of order and were not bucketed"),
		return_misses_expired: z
			.int()
			.describe("Return-to-tier misses where the model's recorded cache TTL had lapsed"),
		return_misses_within_ttl: z
			.int()
			.describe(
				"Return-to-tier misses inside the recorded TTL: the prefix changed or the provider evicted the entry early; billing telemetry cannot distinguish the two",
			),
		return_misses_unknown: z
			.int()
			.describe("Return-to-tier misses with no recorded TTL to attribute against"),
		ttl_5m_turns: z.int().describe("Turns whose cache write used the five-minute TTL"),
		ttl_1h_turns: z.int().describe("Turns whose cache write used the one-hour TTL"),
	})
	.describe(
		"Prompt-caching behaviour of auto-routed turns, bucketed by what the router did.\n\nEvery in-order turn falls in exactly one bucket: the session stayed on the same model,\nvisited a model for the first time (cold by design), or returned to a model it had\nalready used. Out-of-order turns (cross-pod flush races) are counted but not bucketed.",
	);

export const autoRouterBenchmarkGroupSchema = z
	.object({
		sessions: z.int().describe("Sessions overlapping the window, counted whole"),
		turns: z.int().describe("Auto-routed requests on the selected UTC days"),
		total_tokens: z
			.union([z.int(), z.null()])
			.optional()
			.describe(
				"Input and output tokens of routed generation requests on the selected UTC days, excluding classifier tokens; null when any selected requests predate daily token recording",
			),
		avg_turns_per_session: z
			.union([z.number(), z.null()])
			.describe(
				"Lifetime turns per overlapping session; null when the window has routed requests but no session rows for this router type, such as an alias whose router type changed mid-session",
			),
		avg_session_seconds: z
			.union([z.number(), z.null()])
			.describe("Lifetime seconds per overlapping session; null as above"),
		avg_tokens_per_session: z
			.union([z.number(), z.null()])
			.describe("Lifetime tokens per overlapping session; null as above"),
		spend: z.number().describe("What the selected days' routed traffic actually cost"),
		classifier_cost: z
			.union([z.number(), z.null()])
			.describe(
				"Recorded LLM classifier cost already included in spend; null when any session turns predate subtotal recording, and zero for an empty window",
			),
		savings_estimated_turns: z
			.int()
			.describe(
				"Requests compared against the baseline: every request on complexity routers that recorded savings",
			),
		savings_estimated_actual_spend: z
			.number()
			.describe("Actual spend, including classifier cost, for the compared requests"),
		savings_estimated_classifier_cost: z
			.union([z.number(), z.null()])
			.optional()
			.describe(
				"Classifier cost included in the compared actual spend; null when classification costs for those requests are unavailable",
			),
		saved_spend: z
			.union([z.number(), z.null()])
			.describe(
				"Recorded savings on the selected UTC days; null when traffic has no recorded savings estimates. On totals this is the same daily figure the Overall savings view reports",
			),
		unattributed_saved_spend: z
			.union([z.number(), z.null()])
			.optional()
			.describe(
				"Part of saved_spend no router's daily rows account for, such as history recorded before per-router daily tracking; when set, baseline_spend and saved_pct are null",
			),
		baseline_spend: z
			.union([z.number(), z.null()])
			.describe(
				"Estimated single-model cost: compared actual spend plus recorded savings; null when traffic has no recorded savings",
			),
		saved_pct: z
			.union([z.number(), z.null()])
			.describe("Recorded savings over baseline_spend, as a percentage"),
		cache: autoRouterCacheStatsSchema.describe(
			"Prompt-caching behaviour of auto-routed turns, bucketed by what the router did.\n\nEvery in-order turn falls in exactly one bucket: the session stayed on the same model,\nvisited a model for the first time (cold by design), or returned to a model it had\nalready used. Out-of-order turns (cross-pod flush races) are counted but not bucketed.",
		),
		router_name: z.string().describe("The auto-router alias requests were sent to"),
		router_type: z.string().describe("complexity, adaptive or quality"),
		tier_turns: z
			.record(z.string(), z.int())
			.optional()
			.describe(
				"Turns per tier, keyed by the tier name the routing decision recorded at request time (never re-derived at read time, since the tier-to-model mapping is mutable config). Tier names are scoped to this group's router_type and are not comparable across types: a complexity router reports 'SIMPLE'/'MEDIUM'/'COMPLEX'/'REASONING', a quality router reports its numeric quality tier, and an adaptive router records no tier at all. Turns no tier served (the classifier fell back to default_model) are absent rather than pooled under a sentinel key, so the values may sum to less than turns",
			),
	})
	.describe("One auto-router's slice of the benchmarks.");

