export const autoRouterSessionResponseSchema = z
	.object({
		session_id: z.string(),
		router_name: z.string().describe("The auto-router alias the session's requests were sent to"),
		router_type: z.string().describe("complexity, adaptive or quality"),
		turns: z.int().describe("Auto-routed turns the rollup has recorded for this session so far"),
		last_model: z.string().describe("The deployment model the most recent turn was routed to"),
		spend: z
			.number()
			.describe("What the session's routed traffic actually cost, classifier calls included"),
		savings_estimated_turns: z
			.int()
			.describe("Requests whose savings estimate recorded its baseline cost"),
		savings_estimated_actual_spend: z
			.number()
			.describe(
				"Actual spend, including classifier cost, for requests whose estimate recorded its baseline cost",
			),
		saved_spend: z
			.union([z.number(), z.null()])
			.describe("Recorded historical savings plus newer estimates, net of classifier cost"),
		baseline_spend: z
			.union([z.number(), z.null()])
			.describe("Estimated single-model cost: spend plus recorded savings"),
		savings_estimated_baseline_spend: z
			.union([z.number(), z.null()])
			.describe(
				"Estimated single-model cost for requests whose estimate recorded its baseline cost",
			),
		baseline_model: z
			.union([z.string(), z.null()])
			.describe(
				"The savings baseline recorded by most session turns, including historical turns, recorded turn by turn, so it still names the counterfactual after the router is reconfigured or removed. None when no turn recorded one: rows from before the baseline was recorded, and adaptive and quality routers, which derive no baseline and so report no savings",
			),
		baseline_models: z
			.record(z.string(), z.int())
			.describe(
				"Session turns recording each baseline model; more than one entry means the router's baseline changed mid-session; these counts do not imply savings coverage",
			),
	})
	.describe(
		"One auto-routed session as its own key sees it: what the last turn ran on, and what the session cost\nagainst the router's savings baseline (the priciest model in its hardest tier).",
	);

