export const localShellCallActionSchema = z
	.looseObject({
		command: z.array(z.string()),
		env: z.record(z.string(), z.string()),
		type: z.enum(["exec"]),
		timeout_ms: z.union([z.int(), z.null()]).optional(),
		user: z.union([z.string(), z.null()]).optional(),
		working_directory: z.union([z.string(), z.null()]).optional(),
	})
	.describe("Execute a shell command on the server.");

export const localShellCallSchema = z
	.looseObject({
		id: z.string(),
		action: localShellCallActionSchema.describe("Execute a shell command on the server."),
		call_id: z.string(),
		status: z.enum(["in_progress", "completed", "incomplete"]),
		type: z.enum(["local_shell_call"]),
	})
	.describe("A tool call to run a command on the local shell.");

export const localShellCallOutputSchema = z
	.looseObject({
		id: z.string(),
		output: z.string(),
		type: z.enum(["local_shell_call_output"]),
		status: z.union([z.enum(["in_progress", "completed", "incomplete"]), z.null()]).optional(),
	})
	.describe("The output of a local shell tool call.");

export const logprobTopLogprobSchema = z
	.looseObject({
		token: z.string(),
		bytes: z.array(z.int()),
		logprob: z.number(),
	})
	.describe("The top log probability of a token.");

export const logprobSchema = z
	.looseObject({
		token: z.string(),
		bytes: z.array(z.int()),
		logprob: z.number(),
		top_logprobs: z.array(logprobTopLogprobSchema),
	})
	.describe("The log probability of a token.");

export const MCPPublicServerSchema = z
	.object({
		server_id: z.string(),
		name: z.string(),
		alias: z.union([z.string(), z.null()]).optional(),
		server_name: z.union([z.string(), z.null()]).optional(),
		transport: z.enum(["sse", "http", "stdio"]),
		spec_path: z.union([z.string(), z.null()]).optional(),
		auth_type: z
			.union([
				z.enum([
					"none",
					"api_key",
					"bearer_token",
					"basic",
					"authorization",
					"oauth2",
					"aws_sigv4",
					"token",
					"oauth2_token_exchange",
					"oauth2_id_jag",
					"true_passthrough",
					"oauth_delegate",
				]),
				z.null(),
			])
			.optional(),
		mcp_info: z.union([z.looseObject({}), z.null()]).optional(),
	})
	.describe("Safe params for public MCP servers");

export const MCPSemanticFilterSettingsSchema = z
	.object({
		enabled: z
			.boolean()
			.optional()
			.default(false)
			.describe("Enable semantic filtering of MCP tools based on query relevance"),
		embedding_model: z
			.string()
			.optional()
			.default("text-embedding-3-small")
			.describe(
				"Embedding model to use for semantic similarity (e.g., 'text-embedding-3-small', 'text-embedding-ada-002')",
			),
		top_k: z
			.int()
			.min(1)
			.max(100)
			.optional()
			.default(10)
			.describe("Number of most relevant tools to return"),
		similarity_threshold: z
			.number()
			.min(0)
			.max(1)
			.optional()
			.default(0.3)
			.describe(
				"Minimum similarity score for tool inclusion (0.0 to 1.0, where 1.0 = exact match)",
			),
	})
	.describe("Configuration for MCP Semantic Tool Filter");

export const MCPSemanticFilterSettingsResponseSchema = z
	.object({
		values: z.looseObject({}),
		field_schema: z.looseObject({}),
	})
	.describe("Response model for MCP semantic filter settings");

export const MCPToolSearchSettingsSchema = z
	.object({
		embedding_model: z
			.union([z.string(), z.null()])
			.optional()
			.describe(
				"Embedding model from model_list used to rank tools by meaning. Unset keeps keyword matching.",
			),
		top_k: z
			.int()
			.min(1)
			.max(100)
			.optional()
			.default(5)
			.describe(
				"Most ranked tools a search returns. A smaller top_k in the tool call wins. Core tools do not count.",
			),
		similarity_threshold: z
			.number()
			.min(0)
			.max(1)
			.optional()
			.default(0)
			.describe(
				"Lowest cosine similarity a tool needs to appear in semantic results (0.0 = no cutoff).",
			),
		core_tools: z
			.array(z.string())
			.optional()
			.default([])
			.describe(
				"Tool names always returned first when the caller can access them, e.g. `my_server-get_rates`.",
			),
	})
	.describe(
		"`litellm_settings.mcp_tool_search`: how the native `mcp_tool_search` virtual tool ranks the caller's tools.",
	);

export const MCPToolSearchSettingsResponseSchema = z
	.object({
		values: z.looseObject({}),
		field_schema: z.looseObject({}),
	})
	.describe("Response model for native MCP tool search settings");

