export const memoryCreateRequestSchema = z.object({
	key: z.string().describe("Memory key (acts as the namespace in the URL)."),
	value: z.string().describe("Memory content. Typically markdown/text for LLM context."),
	metadata: z
		.union([z.unknown(), z.null()])
		.optional()
		.describe("Optional JSON metadata (tags, structured fields)."),
	user_id: z
		.union([z.string(), z.null()])
		.optional()
		.describe("Scope to this user. Defaults to the caller's user_id."),
	team_id: z
		.union([z.string(), z.null()])
		.optional()
		.describe("Scope to this team. Defaults to the caller's team_id."),
});

export const memoryDeleteResponseSchema = z.object({
	key: z.string(),
	deleted: z.boolean(),
});

export const memoryListResponseSchema = z.object({
	memories: z.array(liteLLMMemoryRowSchema),
	total: z.int(),
});

export const memoryUpdateRequestSchema = z.object({
	value: z.union([z.string(), z.null()]).optional(),
	metadata: z.union([z.unknown(), z.null()]).optional(),
	user_id: z.union([z.string(), z.null()]).optional(),
	team_id: z.union([z.string(), z.null()]).optional(),
});

export const modelDeprecationInfoSchema = z.object({
	model_name: z.string().describe("The public name of the model on the proxy (model_group)."),
	litellm_model: z
		.union([z.string(), z.null()])
		.optional()
		.describe("The underlying litellm model string the deprecation date is sourced from."),
	deprecation_date: z.iso.date().describe("The date (UTC) when the model becomes deprecated."),
	days_until_deprecation: z
		.int()
		.describe(
			"Days remaining until the deprecation date. Negative if the model is already deprecated.",
		),
	status: z
		.enum(["upcoming", "imminent", "deprecated"])
		.describe(
			"'deprecated' if the date has passed, 'imminent' if it falls within warn_within_days, 'upcoming' otherwise.",
		),
	litellm_provider: z
		.union([z.string(), z.null()])
		.optional()
		.describe("The provider this model belongs to."),
});

export const modelDeprecationResponseSchema = z.object({
	deprecated: z
		.array(modelDeprecationInfoSchema)
		.optional()
		.describe("Models whose deprecation date has already passed."),
	imminent: z
		.array(modelDeprecationInfoSchema)
		.optional()
		.describe(
			"Models whose deprecation date is within warn_within_days from today and require immediate migration planning.",
		),
	upcoming: z
		.array(modelDeprecationInfoSchema)
		.optional()
		.describe("Models with a future deprecation date outside the warn window."),
	warn_within_days: z.int().describe("The window (in days) used to bucket 'imminent' models."),
	checked_at: z.iso
		.datetime()
		.describe("UTC timestamp when the deprecation snapshot was generated."),
});

