export const shadowEvalSliceSchema = z
	.object({
		group: z.string(),
		turn_count: z.int(),
		real_win_rate_pct: z
			.number()
			.describe(
				"Share of judged turns the real arm won, meaning the response the caller actually received: the key's own model in forward mode, the router's pick in reverse",
			),
		shadow_win_rate_pct: z
			.number()
			.describe(
				"Share of judged turns the shadow arm won, meaning the duplicated response nobody was served: the router's pick in forward mode, baseline_model in reverse",
			),
		tie_rate_pct: z.number(),
		avg_judge_confidence: z.number(),
		real_spend: z
			.number()
			.optional()
			.default(0)
			.describe(
				"USD the real arm billed on this slice's judged turns, completion plus its own routing classifier when it routed, excluding turns litellm's response cache served for free",
			),
		shadow_spend: z
			.number()
			.optional()
			.default(0)
			.describe(
				"USD the shadow arm billed on the same turns, completion plus its own routing classifier, excluding the judge and the same cache-served turns, so the two spends compare like for like",
			),
		cache_hit_turns: z
			.int()
			.optional()
			.default(0)
			.describe(
				"Judged turns litellm's response cache served, excluded from both spends: an adopted router would be served by the same cache, so those turns cost the same either way",
			),
	})
	.describe(
		"Judge outcomes for one slice of a job's verdicts: a router tier, one of the\nmodels that served the real arm, or one scoped target (embedded on that target's\nown entry, so slices never need re-joining to a target by id).",
	);

export const shadowEvalJobTargetResponseSchema = z
	.object({
		target_type: z.enum(["key", "team", "user"]).describe("What kind of entity this entry scopes"),
		target_id: z
			.string()
			.describe("The hashed virtual key, team id, or user id whose traffic this entry scopes"),
		max_turns: z
			.int()
			.describe(
				"This target's sample-count ceiling: the whole budget for jobs created before max_budget existed, and the error-loop safety valve otherwise",
			),
		max_budget: z
			.union([z.number(), z.null()])
			.optional()
			.describe(
				"This target's own USD budget for the eval's shadow and judge spend, independent of its siblings'; None on jobs created before spend budgets existed, which max_turns alone bounds",
			),
		stopped_at: z
			.union([z.iso.datetime(), z.null()])
			.optional()
			.describe(
				"When this target's slot was stamped free, whether its own budget ran out, the window closed, or an operator stopped the job; status is derived, so a spent budget reads completed even while this is still unset",
			),
		attempt_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe(
				"This target's sampled attempts so far, judged and errored alike, the same count the sampler budgets against max_turns; populated on list and detail responses. Frozen at stopped_at once the target is stamped, so in-flight attempts landing after a stop never reclassify it",
			),
		spend: z
			.union([z.number(), z.null()])
			.optional()
			.describe(
				"This target's recorded shadow plus judge spend in USD, the same figure the sampler budgets against max_budget; populated on list and detail responses and frozen at stopped_at exactly like attempt_count",
			),
		verdicts: z
			.union([shadowEvalSliceSchema, z.null()])
			.optional()
			.describe(
				"This target's own judged-verdict slice; detail endpoint only, None until a turn is judged",
			),
		target_alias: z
			.union([z.string(), z.null()])
			.optional()
			.describe(
				"Display label resolved from the target's own row at read time: the key's alias, the team's alias, or the user's email; None when unset or deleted",
			),
		key_name: z
			.union([z.string(), z.null()])
			.optional()
			.describe(
				"Masked display name (sk-...) for key targets, resolved at read time; None for teams and users",
			),
	})
	.describe("One target a job shadows (a key, team, or user), with its own budget and stop state.");

export const shadowEvalResultSchema = z
	.object({
		by_tier: z.array(shadowEvalSliceSchema),
		by_current_model: z
			.array(shadowEvalSliceSchema)
			.describe(
				"Sliced by the model that served the real arm: the keys' incumbent models in forward mode, and in reverse the models the router itself picked",
			),
		by_router: z
			.array(shadowEvalSliceSchema)
			.optional()
			.default([])
			.describe(
				"One slice per router arm, grouped on the router name. Every arm of a multi-router job is judged against the same real responses over the same sampled requests, so these slices compare routers head-to-head: like-for-like win rates and spends on identical traffic. Verdicts from before arm stamping existed count toward the job's own router",
			),
		overall_shadow_win_rate_pct: z.number(),
		overall_tie_rate_pct: z.number(),
		sampled_real_spend: z
			.number()
			.optional()
			.default(0)
			.describe(
				"USD the real arm billed across all judged turns, cache-served turns excluded. A judged turn is one (request, router arm) verdict, so a multi-router job counts the real response once per arm it was judged against; per-router comparisons read by_router",
			),
		sampled_shadow_spend: z
			.number()
			.optional()
			.default(0)
			.describe("USD the shadow arms billed across the same turns, judge excluded, like for like"),
		not_sampled_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe(
				"Eligible requests the sampling dice skipped, summed over legs: the judged rows stand for judged + this many requests. None for jobs from before the funnel existed",
			),
		unjudgeable_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe("Sampled requests whose shape could not be judged (tool-final turn, empty text)"),
		shed_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe(
				"Sampled requests dropped by the per-pod concurrency cap, so quiet periods are overweighted",
			),
		withheld_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe(
				"Sampled requests the pipeline declined to spend on: no database to record into, an over-budget key or team, or the eval budget unverifiable or already reached (the in-flight burst as a job crosses max_budget lands here rather than vanishing from coverage)",
			),
	})
	.describe("Stratified results of a shadow-eval job's verdicts so far.");

export const shadowEvalJobResponseSchema = z
	.object({
		job_id: z.string(),
		targets: z
			.array(shadowEvalJobTargetResponseSchema)
			.min(1)
			.describe(
				"The targets whose traffic this job evaluates, and only theirs, each with its own budget",
			),
		router_names: z
			.array(z.string())
			.min(1)
			.describe(
				"Every auto-router this job runs as a shadow arm. Multi-router jobs sample one slice of traffic and judge every arm against the same real responses",
			),
		models: z
			.array(z.string())
			.optional()
			.default([])
			.describe(
				"Model groups the sampled traffic is narrowed to; empty means every model the targets use",
			),
		direction: z.enum(["forward", "reverse"]).optional().default("forward"),
		baseline_model: z.union([z.string(), z.null()]).optional(),
		judge_model: z.string(),
		shadow_percentage: z.number(),
		created_at: z.iso.datetime(),
		ends_at: z.iso.datetime(),
		stopped_by: z
			.union([z.string(), z.null()])
			.optional()
			.describe(
				"The operator who stopped the job early, recorded by the stop endpoint; 'unknown' backfilled by migration for jobs that displayed stopped when the column arrived; None when the job ended on its own. Its presence is what makes a job read stopped rather than completed",
			),
		judged_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe("Verdicts recorded; detail endpoint only"),
		error_count: z
			.union([z.int(), z.null()])
			.optional()
			.describe("Sampled attempts that errored; detail endpoint only"),
		judge_spend: z
			.union([z.number(), z.null()])
			.optional()
			.describe("Judge cost so far; detail endpoint only"),
		last_error: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Most recent attempt error; detail endpoint only"),
		results: z
			.union([shadowEvalResultSchema, z.null()])
			.optional()
			.describe("Stratified verdicts; detail endpoint only"),
		router_name: z
			.string()
			.describe(
				"The first router, kept for callers that predate router_names; derived so the\ntwo fields can never disagree.",
			),
		status: z
			.enum(["running", "completed", "stopped"])
			.describe(
				"Three recorded facts, no history-guessing: a stop is stopped_by (the migration\nbackfills it for every job that displayed stopped when the column arrived, so the\npre-column population is closed), completion is the window passing or every target\nspending its budget, and anything else is running. The all-targets-stamped fallback\ncovers only stops written by pre-column pods during a rolling deploy.",
			),
	})
	.describe(
		"A shadow-eval job over one or more targets, each with its own budget and stop state;\nstatus is derived from stopped_by, the targets' stop and budget state, and ends_at,\nnever stored, so no writer anywhere can produce an inconsistent one. Aggregate\nfields are populated by the detail endpoint only and stay None on list responses.",
	);

