export const contentFilterActionSchema = z
	.enum(["BLOCK", "MASK"])
	.describe("Action to take when content filter detects a match");

export const blockedWordSchema = z
	.object({
		action: contentFilterActionSchema.describe(
			"Action to take when keyword is detected (BLOCK or MASK)",
		),
		description: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Optional description explaining why this keyword is sensitive"),
		keyword: z.string().describe("The keyword to block or mask"),
	})
	.describe("Represents a blocked word with its action and optional description");

export const contentFilterCategoryConfigSchema = z
	.looseObject({
		action: z.enum(["BLOCK", "MASK"]).describe("The action to take when the category is detected"),
		category: z.string().describe("The category to detect"),
		category_file: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Optional override. Use your own category file instead of the default one."),
		enabled: z.boolean().optional().default(true).describe("Whether the category is enabled"),
		severity_threshold: z
			.enum(["high", "medium", "low"])
			.optional()
			.default("medium")
			.describe("The severity threshold to detect the category"),
	})
	.describe(
		'category: "harmful_self_harm"\n              enabled: true\n              action: "BLOCK"\n              severity_threshold: "medium"\n              category_file: "/path/to/custom_file.yaml"  # optional override',
	);

export const lakeraCategoryThresholdsSchema = z.looseObject({
	jailbreak: z.number().optional(),
	prompt_injection: z.number().optional(),
});

export const contentFilterPatternSchema = z
	.object({
		action: contentFilterActionSchema.describe(
			"Action to take when pattern matches (BLOCK or MASK)",
		),
		name: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Name for this pattern (used in logging and error messages)"),
		pattern: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Custom regex pattern. Required if pattern_type is 'regex'"),
		pattern_name: z
			.union([z.string(), z.null()])
			.optional()
			.describe(
				"Name of prebuilt pattern (e.g., 'us_ssn', 'credit_card'). Required if pattern_type is 'prebuilt'",
			),
		pattern_type: z
			.enum(["prebuilt", "regex"])
			.describe("Type of pattern: 'prebuilt' for predefined patterns or 'regex' for custom"),
	})
	.describe("Represents a content filter pattern (prebuilt or custom regex)");

