export const decisionsBoxSchema = z.looseObject({
	bottom: z.number(),
	left: z.number(),
	right: z.number(),
	top: z.number(),
});

export const boxAnswerSchema = z.looseObject({
	box: decisionsBoxSchema,
	confidence: z.union([z.number(), z.null()]),
	type: z.enum(["box"]),
});

export const choiceAnswerSchema = z.looseObject({
	choice: z.string(),
	confidence: z.number(),
	probabilities: z.record(z.string(), z.number()),
	type: z.enum(["choice"]),
});

export const noulAnswerSchema = z.looseObject({
	noul: z.number(),
	type: z.enum(["noul"]),
});

export const scoreAnswerSchema = z.looseObject({
	confidence: z.number(),
	legend: z.record(z.string(), z.union([z.string(), z.looseObject({}), z.array(z.unknown())])),
	probabilities: z.record(z.string(), z.number()),
	score: z.number(),
	type: z.enum(["score"]),
});

export const decisionsUsageSchema = z.looseObject({
	input_tokens: z.int().optional().default(0),
	output_tokens: z.int().optional().default(0),
});

export const decisionsResponseSchema = z.looseObject({
	answers: z.record(
		z.string(),
		z.discriminatedUnion("type", [
			noulAnswerSchema.extend({
				type: z.enum(["noul"]),
			}),
			choiceAnswerSchema.extend({
				type: z.enum(["choice"]),
			}),
			scoreAnswerSchema.extend({
				type: z.enum(["score"]),
			}),
			boxAnswerSchema.extend({
				type: z.enum(["box"]),
			}),
		]),
	),
	model: z.union([z.string(), z.null()]).optional(),
	usage: z.union([decisionsUsageSchema, z.null()]).optional(),
});

