export const registerPluginRequestSchema = z
	.object({
		author: z.union([pluginAuthorSchema, z.null()]).optional().describe("Plugin author"),
		category: z.union([z.string(), z.null()]).optional().describe("Plugin category"),
		description: z.union([z.string(), z.null()]).optional().describe("Plugin description"),
		domain: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Skill domain (e.g., 'Productivity')"),
		homepage: z.union([z.string(), z.null()]).optional().describe("Plugin homepage URL"),
		keywords: z
			.union([z.array(z.string()), z.null()])
			.optional()
			.describe("Search keywords"),
		name: z
			.string()
			.regex(/^[a-z0-9-]+$/)
			.describe("Plugin name (kebab-case, e.g., 'my-plugin')"),
		namespace: z
			.union([z.string(), z.null()])
			.optional()
			.describe("Skill namespace within domain (e.g., 'workflows')"),
		source: z
			.record(z.string(), z.string())
			.describe(
				"Plugin source reference. Supported formats:\n- GitHub: {'source': 'github', 'repo': 'org/repo'}\n- Git URL: {'source': 'url', 'url': 'https://github.com/org/repo.git'}\n- Git Subdir: {'source': 'git-subdir', 'url': 'https://github.com/org/repo.git', 'path': 'plugins/plugin-name'}\n- Zip archive on any https host (e.g. S3): {'source': 'archive', 'url': 'https://bucket.s3.amazonaws.com/plugin.zip', 'sha256': '<optional hex digest>'}",
			),
		version: z
			.union([z.string(), z.null()])
			.optional()
			.default("1.0.0")
			.describe("Semantic version"),
	})
	.describe(
		"Request body for registering a plugin in the marketplace.\n\nLiteLLM acts as a registry/discovery layer. Plugins are hosted on\nGitHub/GitLab/Bitbucket or as a zip archive on any https host and referenced by their source.",
	);

