export const decisionsDecisionsPostBodySchema = z.looseObject({
	audio: z
		.array(
			z.union([
				z.string().regex(/^data:audio\/[^;,\s]+;base64,.+$/),
				z.strictObject({
					base64: z.string().min(1).describe("Base64-encoded audio bytes"),
					content_type: z
						.string()
						.regex(/^audio\/\S+$/)
						.describe("An audio/* media type, such as audio/wav"),
				}),
			]),
		)
		.max(4)
		.optional()
		.default([])
		.describe(
			"Clef-omni only. Up to 4 embedded audio clips, each a base64 data URL or {content_type, base64}",
		),
	input: z
		.union([
			z.string(),
			z.array(
				z.strictObject({
					content: z.union([
						z.string(),
						z.array(
							z.discriminatedUnion("type", [
								z.strictObject({
									text: z.string(),
									type: z.enum(["input_text"]),
								}),
								z.strictObject({
									detail: z.union([z.string(), z.null()]).optional(),
									image_url: z.string(),
									type: z.enum(["input_image"]),
								}),
							]),
						),
					]),
					role: z.enum(["user"]).optional().default("user"),
					type: z.enum(["message"]).optional().default("message"),
				}),
			),
		])
		.describe(
			"The text being judged, or user messages whose content mixes input_text and input_image parts",
		),
	model: z.string().describe("A decision model from the proxy model_list"),
	questions: z
		.array(
			z.discriminatedUnion("type", [
				z.strictObject({
					instructions: z.string().describe("The yes/no question to ask about the input"),
					name: z
						.union([z.string(), z.null()])
						.optional()
						.describe("Echoed in the matching answer"),
					type: z.enum(["predicate"]),
				}),
				z.strictObject({
					choices: z
						.array(
							z.strictObject({
								description: z.union([z.string(), z.null()]).optional(),
								value: z.union([z.string(), z.boolean()]),
							}),
						)
						.min(2)
						.max(255)
						.describe("The options the model picks from. Values must be unique"),
					instructions: z.string().describe("The question to ask about the input"),
					name: z
						.union([z.string(), z.null()])
						.optional()
						.describe("Echoed in the matching answer"),
					type: z.enum(["choice"]),
				}),
				z.strictObject({
					instructions: z.string().describe("The question to ask about the input"),
					levels: z
						.array(
							z.strictObject({
								description: z.union([z.string(), z.null()]).optional(),
								label: z.string(),
							}),
						)
						.min(2)
						.max(10)
						.describe("Scale levels from lowest to highest. The score is a level index"),
					name: z
						.union([z.string(), z.null()])
						.optional()
						.describe("Echoed in the matching answer"),
					type: z.enum(["score"]),
				}),
				z.strictObject({
					instructions: z.string().describe("What to find in the input's image"),
					name: z
						.union([z.string(), z.null()])
						.optional()
						.describe("Echoed in the matching answer"),
					type: z.enum(["box"]),
				}),
			]),
		)
		.min(1)
		.max(128)
		.describe("Predicate, choice and score questions. Answers come back in the same order"),
	safety_identifier: z
		.union([z.string(), z.null()])
		.optional()
		.describe("A stable id for your end user. Sent to OpenAI and dropped for other providers"),
	videos: z
		.array(
			z.union([
				z.string().regex(/^data:video\/[^;,\s]+;base64,.+$/),
				z.strictObject({
					base64: z.string().min(1).describe("Base64-encoded video bytes"),
					content_type: z
						.string()
						.regex(/^video\/\S+$/)
						.describe("A video/* media type, such as video/mp4"),
				}),
			]),
		)
		.max(2)
		.optional()
		.default([])
		.describe(
			"Clef-omni only. Up to 2 embedded videos, each a base64 data URL or {content_type, base64}",
		),
});

